def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                marks[c - r] = grid[r][c]

    if not marks:
        return grid

    # Find the shortest diagonal repeat that keeps differently colored
    # marked diagonals in separate residue classes.
    period = 1
    while True:
        compatible = True
        for a, ca in marks.items():
            for b, cb in marks.items():
                if (a - b) % period == 0 and ca != cb:
                    compatible = False
                    break
            if not compatible:
                break
        if compatible:
            break
        period += 1

    values = {}
    for d, color in marks.items():
        values[d % period] = color

    residues = sorted(values)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            residue = (c - r) % period
            if residue in values:
                row.append(values[residue])
            else:
                nearest = min(residues,
                              key=lambda x: min((residue-x) % period, (x-residue) % period))
                row.append(values[nearest])
        out.append(row)
    return out
